def top_frequent_words(text, k):
    """Finds top k most frequent words ignoring casing, punctuation, and stop words."""
    if not text or k <= 0: return []
    stop_words = {'the', 'a', 'an', 'is', 'in', 'it', 'to', 'of', 'and'}
    cleaned_words = []
    for raw_word in text.split():
        w = ''.join(c.lower() for c in raw_word if c.isalnum())
        if w and w not in stop_words:
            cleaned_words.append(w)
    counts = {}
    for w in cleaned_words:
        counts[w] = counts.get(w, 0) + 1
    sorted_words = sorted(counts.keys(), key=lambda w: (-counts[w], w))
    return sorted_words[:k]
